HTML=r"""<div id='rv'><div class='bar'><button id='fit'>Fit page</button><button data-z='1'>100%</button><button data-z='1.5'>150%</button><button data-z='2'>200%</button><button id='up'>↑</button><button id='left'>←</button><button id='centre'>Centre</button><button id='right'>→</button><button id='down'>↓</button></div><div class='bar'><button id='add'>ADD</button><button id='erase'>ERASE</button><button id='off'>NAVIGATE</button><button id='undo'>Undo</button><button id='redo'>Redo</button><label>Brush <input id='brush' type='range' min='2' max='60' value='14'></label></div><div class='bar'><label>Confidence <input id='threshold' type='range' min='0' max='100' value='20'></label><label>Opacity <input id='opacity' type='range' min='0' max='100' value='65'></label><label><input id='original' type='checkbox' checked>Original</label><label><input id='prediction' type='checkbox' checked>Prediction</label><label><input id='adds' type='checkbox' checked>Additions</label><label><input id='erases' type='checkbox' checked>Erasures</label><label><input id='final' type='checkbox'>Final mask</label></div><div id='vp'><canvas id='display' width='900' height='560'></canvas></div><button id='authorise'>Authorise reviewed mask</button></div>"""
JS=r"""async(...args)=>{const $=x=>document.getElementById(x),C=$('display'),X=C.getContext('2d'),W=900,H=560;let P=null,I=null,D=null,F=null,A=null,E=null,mode='off',zoom=1,px=0,py=0,ops=[],redo=[],active=null;const load=s=>new Promise((r,j)=>{let i=new Image();i.onload=()=>r(i);i.onerror=j;i.src=s});function mc(w,h){let c=document.createElement('canvas');c.width=w;c.height=h;return c}function redraw(){if(!P)return;for(let c of [A,E])c.getContext('2d').clearRect(0,0,c.width,c.height);for(let o of ops){let x=(o.m==='add'?A:E).getContext('2d');x.strokeStyle='white';x.fillStyle='white';x.lineWidth=o.b;x.lineCap='round';x.lineJoin='round';x.beginPath();o.p.forEach((p,i)=>i?x.lineTo(...p):x.moveTo(...p));x.stroke()}render()}function fit(){if(!P)return;zoom=Math.min(W/P.width,H/P.height);px=(P.width-W/zoom)/2;py=(P.height-H/zoom)/2;clamp();render()}function clamp(){if(!P)return;let vw=W/zoom,vh=H/zoom;px=Math.max(0,Math.min(Math.max(0,P.width-vw),px));py=Math.max(0,Math.min(Math.max(0,P.height-vh),py))}function render(){X.fillStyle='#999';X.fillRect(0,0,W,H);if(!P)return;let vw=W/zoom,vh=H/zoom;X.save();X.scale(zoom,zoom);X.translate(-px,-py);if($('original').checked)X.drawImage(I,0,0);else{X.fillStyle='white';X.fillRect(0,0,P.width,P.height)}X.globalAlpha=+$('opacity').value/100;if($('prediction').checked)X.drawImage(D,0,0);if($('adds').checked)X.drawImage(A,0,0);if($('erases').checked)X.drawImage(E,0,0);X.globalAlpha=1;if($('final').checked){let t=mc(P.width,P.height),q=t.getContext('2d');q.drawImage(D,0,0);q.drawImage(A,0,0);q.globalCompositeOperation='destination-out';q.drawImage(E,0,0);X.fillStyle='white';X.fillRect(0,0,P.width,P.height);X.drawImage(t,0,0)}X.restore()}function bridge(){return document.querySelector('#action-bridge textarea')||document.querySelector('#action-bridge input')}function send(){let h=bridge(),v=JSON.stringify({action:'save',add:A.toDataURL(),erase:E.toDataURL()});let p=h.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;Object.getOwnPropertyDescriptor(p,'value').set.call(h,v);h.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText'}));h.dispatchEvent(new Event('change',{bubbles:true}))}async function ingest(raw){let n=JSON.parse(raw),q=await Promise.all([load(n.image),load(n.draft),load(n.confidence)]);P=n;[I,D,F]=q;A=mc(P.width,P.height);E=mc(P.width,P.height);ops=[];redo=[];fit()}window.hitlIngest=ingest;function sm(m){mode=m;['add','erase','off'].forEach(x=>$(x).classList.toggle('active',x===m))}$('fit').onclick=fit;document.querySelectorAll('[data-z]').forEach(b=>b.onclick=()=>{zoom=+b.dataset.z;clamp();render()});$('centre').onclick=()=>{px=Math.max(0,(P.width-W/zoom)/2);py=Math.max(0,(P.height-H/zoom)/2);render()};[['up',0,-.25],['down',0,.25],['left',-.25,0],['right',.25,0]].forEach(([id,x,y])=>$(id).onclick=()=>{px+=x*W/zoom;py+=y*H/zoom;clamp();render()});$('add').onclick=()=>sm('add');$('erase').onclick=()=>sm('erase');$('off').onclick=()=>sm('off');$('undo').onclick=()=>{if(ops.length)redo.push(ops.pop());redraw()};$('redo').onclick=()=>{if(redo.length)ops.push(redo.pop());redraw()};$('authorise').onclick=send;document.querySelectorAll('#rv input').forEach(x=>x.oninput=render);function pt(e){let r=C.getBoundingClientRect();return [px+(e.clientX-r.left)/zoom,py+(e.clientY-r.top)/zoom]}C.onpointerdown=e=>{e.preventDefault();if(mode==='off')return;C.setPointerCapture(e.pointerId);active={m:mode,b:+$('brush').value,p:[pt(e)]}};C.onpointermove=e=>{if(!active)return;e.preventDefault();active.p.push(pt(e));ops.push(active);redraw();active=ops.pop()};C.onpointerup=e=>{if(active){ops.push(active);active=null;redo=[];redraw()}};C.onpointercancel=C.onpointerup;C.oncontextmenu=e=>e.preventDefault();sm('off');return []}"""
CSS=r""".bridge-offscreen{position:fixed!important;left:-10000px!important;width:1px!important;height:1px!important;opacity:0!important}#rv{max-width:960px;margin:auto}.bar{display:flex;gap:5px;flex-wrap:wrap;align-items:center;margin:5px 0}#rv button{min-height:42px;padding:7px 10px}#rv button.active{background:#205493;color:white}#vp{width:100%;height:560px;overflow:hidden;background:#999;border:1px solid #777;touch-action:none;overscroll-behavior:contain}#display{display:block;width:900px;height:560px;max-width:100%;touch-action:none;-webkit-touch-callout:none;user-select:none}"""
